  <main class="tc-shell">
    <section class="tc-game-layout">
      <section class="tc-playfield-column" aria-label="Tension Cores player board surface">
        <div class="tc-playfield-frame">
          <p id="tc-top-side-label" class="tc-side-label tc-side-top">BOT · TOP SIDE</p>
          <canvas id="tension-cores-board" aria-label="Tension Cores playable board"></canvas>
          <p id="tc-bottom-side-label" class="tc-side-label tc-side-bottom">YOU · BOTTOM SIDE</p>
          <div class="tc-touch-controls" aria-label="Touch controls">
            <button id="tc-touch-left-button" class="tc-touch-button tc-touch-button-left" type="button" aria-label="Move aim left">LEFT</button>
            <button id="tc-touch-fire-button" class="tc-touch-button tc-touch-button-fire" type="button" aria-label="Fire core">FIRE</button>
            <button id="tc-touch-right-button" class="tc-touch-button tc-touch-button-right" type="button" aria-label="Move aim right">RIGHT</button>
          </div>
          <section class="tc-mobile-shot-queue" aria-label="Current and upcoming cores">
            <p class="tc-mobile-shot-row">
              <span class="tc-mobile-shot-label">CURRENT</span>
              <span id="tc-mobile-current-core-value" class="tc-mobile-shot-value">RED</span>
              <span id="tc-mobile-current-core-swatch" class="tc-next-core-swatch" aria-hidden="true"></span>
            </p>
            <p class="tc-mobile-shot-row">
              <span class="tc-mobile-shot-label">UP NEXT</span>
              <span id="tc-mobile-up-next-value-1" class="tc-mobile-shot-value">BLUE</span>
              <span id="tc-mobile-up-next-swatch-1" class="tc-next-core-swatch" aria-hidden="true"></span>
              <span id="tc-mobile-up-next-value-2" class="tc-mobile-shot-value">GREEN</span>
              <span id="tc-mobile-up-next-swatch-2" class="tc-next-core-swatch" aria-hidden="true"></span>
            </p>
          </section>
          <div class="tc-mobile-session-controls" aria-label="Mobile session controls">
            <button id="tc-mobile-start-button" class="tc-mobile-session-button" type="button">Start</button>
            <button id="tc-mobile-restart-button" class="tc-mobile-session-button" type="button" disabled>Restart</button>
          </div>
        </div>
      </section>
      <aside class="tc-sidebar-column" aria-label="Player-facing threat and controls sidebar">
        <header class="tc-header">
          <p class="tc-eyebrow">Phase 13K · player-facing layout rework</p>
          <h1>Tension Cores MVP</h1>
          <p id="tc-result-label" class="tc-result" aria-live="polite">Press Start to begin.</p>
        </header>

        <section class="tc-threat-panels">
          <article id="tc-threat-bot-panel" class="tc-threat-panel tc-threat-bot" aria-label="BOT base threat">
            <p class="tc-threat-heading"><span class="tc-threat-label">BOT BASE</span> <span id="tc-bot-base-value">20/20</span></p>
            <p class="tc-threat-row"><span class="tc-threat-label">INCOMING</span> <span id="tc-bot-incoming-value">+0</span></p>
            <p id="tc-bot-state-value" class="tc-threat-state">STABLE</p>
          </article>

          <article id="tc-threat-you-panel" class="tc-threat-panel tc-threat-you" aria-label="YOU base threat">
            <p class="tc-threat-heading"><span class="tc-threat-label">YOU BASE</span> <span id="tc-you-base-value">20/20</span></p>
            <p class="tc-threat-row"><span class="tc-threat-label">INCOMING</span> <span id="tc-you-incoming-value">+0</span></p>
            <p id="tc-you-state-value" class="tc-threat-state">STABLE</p>
            <p class="tc-next-core-panel">
              <span class="tc-next-core-title">YOUR NEXT CORE</span>
              <span id="tc-next-core-value" class="tc-next-core-value">RED</span>
              <span id="tc-next-core-swatch" class="tc-next-core-swatch" aria-hidden="true"></span>
            </p>
            <p class="tc-up-next-panel">
              <span class="tc-next-core-title">UP NEXT</span>
              <span id="tc-up-next-value-1" class="tc-up-next-value">BLUE</span>
              <span id="tc-up-next-swatch-1" class="tc-next-core-swatch" aria-hidden="true"></span>
              <span id="tc-up-next-value-2" class="tc-up-next-value">GREEN</span>
              <span id="tc-up-next-swatch-2" class="tc-next-core-swatch" aria-hidden="true"></span>
            </p>
          </article>
        </section>

        <p id="tc-causal-hint" class="tc-causal-hint" aria-live="polite">YOU are bottom. Match 3 same colors to send pressure to BOT.</p>

        <section class="tc-controls-block">
          <div class="tc-controls">
            <button id="tc-start-button" type="button">Start</button>
            <button id="tc-restart-button" type="button" disabled>Restart</button>
            <button id="tc-debug-button" type="button" aria-pressed="false">Show Debug</button>
          </div>
          <p class="tc-controls-help">Enter/Start begins match · ArrowLeft/ArrowRight aim · Space shoots · R restarts after result · Mobile: LEFT/RIGHT/FIRE.</p>
        </section>

        <details class="tc-rules">
          <summary>Rules</summary>
          <ul id="tc-rule-list">${vr}</ul>
        </details>

        <section class="tc-diagnostics" aria-label="Diagnostics / Match trace">
          <p class="tc-diagnostics-title">Diagnostics / Match trace</p>
          <div class="tc-diagnostics-controls">
            <button id="tc-export-trace-json-button" type="button" disabled>Export trace JSON</button>
            <button id="tc-export-trace-txt-button" type="button" disabled>Export trace TXT</button>
          </div>
        </section>
      </aside>
    </section>
  </main>
